assert len(P)==40 and len(N)==40
with open(__file__.replace("make_style2.py","style2.jsonl"),"w") as f:
    for i,(p,m,a,q) in enumerate(P):
        assert a in m
        f.write(json.dumps({"id":f"s2p{i}","prompt":p,"label":1,"domain":"mixed","memory_record":m,"answer_substr":a,"query_terms":q.split()})+"\n")
    for i,(p,k) in enumerate(N):
        f.write(json.dumps({"id":f"s2n{i}","prompt":p,"label":0,"domain":"mixed","kind":k})+"\n")
